import { Bot, GrammyError, HttpError } from "grammy";
import { log, safeErr } from "./lib/log.js";
import { registerAdminNaturalHandler } from "./features/adminHandlers.js";
import { registerStudentNaturalHandler } from "./features/studentHandlers.js";

export function createBot(token) {
  const bot = new Bot(token);

  bot.catch((err) => {
    const ctx = err.ctx;
    const error = err.error;
    if (error instanceof GrammyError) {
      log.error("telegram api error", { updateId: ctx.update.update_id, code: error.error_code, description: error.description });
      return;
    }
    if (error instanceof HttpError) {
      log.error("telegram http error", { updateId: ctx.update.update_id, error: safeErr(error) });
      return;
    }
    log.error("bot middleware error", { updateId: ctx.update.update_id, error: safeErr(error) });
  });

  return bot;
}

export function registerBotFeatures(bot) {
  registerAdminNaturalHandler(bot);
  registerStudentNaturalHandler(bot);
}

