import "dotenv/config";
import { run } from "@grammyjs/runner";
import { cfg, logEnvSanity } from "./lib/config.js";
import { log, safeErr } from "./lib/log.js";

let runnerHandle = null;
let stopping = false;

process.on("unhandledRejection", (err) => {
  log.error("unhandled rejection", { error: safeErr(err) });
  process.exit(1);
});

process.on("uncaughtException", (err) => {
  log.error("uncaught exception", { error: safeErr(err) });
  process.exit(1);
});

function sleep(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

function logMemory() {
  const m = process.memoryUsage();
  console.log("[mem]", { rssMB: Math.round(m.rss / 1e6), heapUsedMB: Math.round(m.heapUsed / 1e6) });
}

async function stopRunner() {
  if (!runnerHandle) return;
  try {
    await runnerHandle.stop();
  } catch (err) {
    log.warn("runner stop failed", { error: safeErr(err) });
  } finally {
    runnerHandle = null;
  }
}

async function startPolling(bot) {
  let backoffMs = 2000;
  while (!stopping) {
    try {
      log.info("polling start", { platform: "telegram" });
      runnerHandle = run(bot);
      await runnerHandle.task();
      if (!stopping) log.warn("polling stopped unexpectedly", {});
      backoffMs = 2000;
    } catch (err) {
      const message = safeErr(err);
      log.error("polling failure", { platform: "telegram", error: message });
      await stopRunner();
      if (stopping) return;
      if (message.includes("409") || message.toLowerCase().includes("conflict")) {
        log.warn("telegram polling conflict, backing off", { backoffMs });
      }
      await sleep(backoffMs);
      backoffMs = Math.min(backoffMs === 2000 ? 5000 : backoffMs * 2, 20000);
    }
  }
}

async function boot() {
  try {
    log.info("boot start", { platform: "telegram" });
    logEnvSanity();

    if (!cfg.TELEGRAM_BOT_TOKEN) {
      console.error("TELEGRAM_BOT_TOKEN is required. Add it in the CookMyBots Config tab or .env, then redeploy.");
      process.exit(1);
    }

    const { createBot, registerBotFeatures } = await import("./bot.js");
    const { registerCommands } = await import("./commands/loader.js");

    const bot = createBot(cfg.TELEGRAM_BOT_TOKEN);
    await bot.init();
    await registerCommands(bot);
    registerBotFeatures(bot);

    await bot.api.deleteWebhook({ drop_pending_updates: true });
    log.info("telegram webhook cleared", { dropPendingUpdates: true });

    await bot.api.setMyCommands([
      { command: "start", description: "Official greeting and examples" },
      { command: "help", description: "Show student and admin capabilities" },
      { command: "announcements", description: "View active announcements" },
      { command: "latest", description: "Latest announcement or notice" },
      { command: "timetable", description: "View timetable entries" },
      { command: "course", description: "Find course information" },
      { command: "lecturer", description: "Find lecturer details" },
      { command: "department", description: "Department info, fees, contacts, office" },
      { command: "admin", description: "Verify admin access" },
      { command: "addannouncement", description: "Admin add announcement" },
      { command: "updateannouncement", description: "Admin update announcement" },
      { command: "deleteannouncement", description: "Admin delete announcement" },
      { command: "activeannouncements", description: "Admin active announcements" },
      { command: "addlecturer", description: "Admin add lecturer" },
      { command: "updatelecturer", description: "Admin update lecturer" },
      { command: "findlecturer", description: "Admin find lecturer" },
      { command: "addcourse", description: "Admin add course" },
      { command: "updatecourse", description: "Admin update course" },
      { command: "updatetimetable", description: "Admin add timetable entry" },
      { command: "departmentinfo", description: "Admin upsert department info" }
    ]);

    setInterval(logMemory, 60000).unref();

    process.once("SIGTERM", async () => {
      stopping = true;
      await stopRunner();
      process.exit(0);
    });
    process.once("SIGINT", async () => {
      stopping = true;
      await stopRunner();
      process.exit(0);
    });

    await startPolling(bot);
  } catch (err) {
    log.error("boot failure", { error: safeErr(err), code: err?.code || "" });
    if (err?.code === "ERR_MODULE_NOT_FOUND") {
      console.error("Check that all imported files exist and relative ESM imports include .js extensions.");
    }
    process.exit(1);
  }
}

boot();

