import { MongoClient } from "mongodb";
import { log, safeErr } from "./log.js";

let client = null;
let db = null;

export async function getDb(mongoUri) {
  if (!mongoUri) return null;
  if (db) return db;

  try {
    client = new MongoClient(mongoUri, { maxPoolSize: 5, ignoreUndefined: true });
    await client.connect();
    db = client.db();
    await db.collection("memory_messages").createIndex({ platform: 1, userId: 1, chatId: 1, ts: -1 });
    await db.collection("admin_audit").createIndex({ ts: -1 });
    log.info("db connected", { collections: ["memory_messages", "admin_audit"] });
    return db;
  } catch (err) {
    log.error("db connect failed", { collection: "memory_messages", operation: "connect", error: safeErr(err) });
    return null;
  }
}

log.js.content:
export function safeErr(err) {
  return err?.response?.data?.error?.message ||
    err?.response?.data?.message ||
    err?.message ||
    String(err);
}

export const log = {
  info(message, meta = {}) {
    console.log(JSON.stringify({ level: "info", message, ...meta }));
  },
  warn(message, meta = {}) {
    console.warn(JSON.stringify({ level: "warn", message, ...meta }));
  },
  error(message, meta = {}) {
    console.error(JSON.stringify({ level: "error", message, ...meta }));
  }
};

memory.js.content:
import { getDb } from "./db.js";
import { log, safeErr } from "./log.js";

const MEMORY_COLLECTION = "memory_messages";
const inMemoryTurns = [];
const MAX_IN_MEMORY_TURNS = 500;

function pushFallback(doc) {
  inMemoryTurns.push(doc);
  while (inMemoryTurns.length > MAX_IN_MEMORY_TURNS) inMemoryTurns.shift();
}

export async function addTurn({ mongoUri, platform, userId, chatId, role, text }) {
  const doc = {
    platform: String(platform || "whatsapp"),
    userId: String(userId || ""),
    chatId: chatId ? String(chatId) : "",
    role: String(role || "user"),
    text: String(text || "").slice(0, 2000),
    createdAt: new Date(),
    ts: new Date()
  };

  const db = await getDb(mongoUri);
  if (!db) {
    pushFallback(doc);
    return;
  }

  try {
    await db.collection(MEMORY_COLLECTION).insertOne(doc);
  } catch (err) {
    log.error("db write failed", { collection: MEMORY_COLLECTION, operation: "insertOne", error: safeErr(err) });
    pushFallback(doc);
  }
}

export async function getRecentTurns({ mongoUri, platform, userId, chatId, limit = 10 }) {
  const q = {
    platform: String(platform || "whatsapp"),
    userId: String(userId || "")
  };
  if (chatId) q.chatId = String(chatId);

  const db = await getDb(mongoUri);
  if (!db) {
    return inMemoryTurns
      .filter((item) => item.platform === q.platform && item.userId === q.userId && (!q.chatId || item.chatId === q.chatId))
      .slice(-limit)
      .map((item) => ({ role: item.role, text: item.text }));
  }

  try {
    const rows = await db.collection(MEMORY_COLLECTION).find(q).sort({ ts: -1 }).limit(limit).toArray();
    return rows.reverse().map((item) => ({ role: item.role, text: item.text }));
  } catch (err) {
    log.error("db read failed", { collection: MEMORY_COLLECTION, operation: "find", error: safeErr(err) });
    return [];
  }
}

export async function clearUserMemory({ mongoUri, platform, userId, chatId }) {
  const q = {
    platform: String(platform || "whatsapp"),
    userId: String(userId || "")
  };
  if (chatId) q.chatId = String(chatId);

  for (let i = inMemoryTurns.length - 1; i >= 0; i -= 1) {
    const item = inMemoryTurns[i];
    if (item.platform === q.platform && item.userId === q.userId && (!q.chatId || item.chatId === q.chatId)) {
      inMemoryTurns.splice(i, 1);
    }
  }

  const db = await getDb(mongoUri);
  if (!db) return;

  try {
    await db.collection(MEMORY_COLLECTION).deleteMany(q);
  } catch (err) {
    log.error("db write failed", { collection: MEMORY_COLLECTION, operation: "deleteMany", error: safeErr(err) });
  }
}

export async function auditAdminAction({ mongoUri, userId, action, sheet, target, ok, details = {} }) {
  const db = await getDb(mongoUri);
  if (!db) return;

  try {
    await db.collection("admin_audit").insertOne({
      platform: "whatsapp",
      userId: String(userId || ""),
      action: String(action || ""),
      sheet: String(sheet || ""),
      target: String(target || ""),
      ok: Boolean(ok),
      details,
      createdAt: new Date(),
      ts: new Date()
    });
  } catch (err) {
    log.error("db write failed", { collection: "admin_audit", operation: "insertOne", error: safeErr(err) });
  }
}

departmentRecords.js.content:
import { listRows } from "./googleSheets.js";

export const NO_DATA_MESSAGE = "I don’t have confirmed information on that yet. Please check back later or contact the Department of Software Engineering representative.";

export function normalize(value) {
  return String(value || "").toLowerCase().replace(/[^a-z0-9]+/g, " ").trim();
}

export function extractCourseCode(text) {
  const match = String(text || "").match(/\b([A-Z]{2,4})\s*-?\s*(\d{3})\b/i);
  return match ? `${match[1].toUpperCase()} ${match[2]}` : "";
}

export function extractLevel(text) {
  const match = String(text || "").match(/\b([1-6]00)\s*(level|lvl)?\b/i);
  return match ? match[1] : "";
}

export function extractDay(text) {
  const days = ["monday", "tuesday", "wednesday", "thursday", "friday", "saturday", "sunday"];
  const normalized = normalize(text);
  if (normalized.includes("today")) return new Intl.DateTimeFormat("en-US", { weekday: "long" }).format(new Date());
  return days.find((day) => normalized.includes(day)) || "";
}

function isActive(row, { includeOld = false } = {}) {
  const status = normalize(row.Status || "active");
  if (!["", "active", "current", "published"].includes(status)) return false;
  if (!includeOld && row.ExpiryDate) {
    const expiry = new Date(row.ExpiryDate);
    if (!Number.isNaN(expiry.getTime())) {
      const today = new Date();
      today.setHours(0, 0, 0, 0);
      if (expiry < today) return false;
    }
  }
  return true;
}

function scoreAnnouncement(row) {
  const priority = Number(row.Priority || 0);
  const date = new Date(row.DatePosted || 0).getTime() || 0;
  return priority * 10000000000000 + date;
}

function containsAny(row, query, fields) {
  const q = normalize(query);
  if (!q) return true;
  return fields.some((field) => normalize(row[field]).includes(q) || q.includes(normalize(row[field])));
}

export async function findAnnouncements(query = "", opts = {}) {
  const level = extractLevel(query);
  const course = extractCourseCode(query);
  const q = normalize(query);
  const rows = (await listRows("Announcements")).filter((row) => isActive(row, opts));

  return rows
    .filter((row) => {
      if (level && normalize(row.Level) !== normalize(level)) return false;
      if (course && normalize(row.CourseCode) !== normalize(course)) return false;
      if (!level && !course && q) {
        const ignored = ["announcement", "announcements", "latest", "active", "show", "me", "department", "today", "notice", "notices"];
        const meaningful = q.split(" ").filter((word) => !ignored.includes(word)).join(" ");
        if (meaningful && !containsAny(row, meaningful, ["Title", "Category", "Level", "CourseCode", "Message"])) return false;
      }
      return true;
    })
    .sort((a, b) => scoreAnnouncement(b) - scoreAnnouncement(a));
}

export async function findLatest() {
  const announcements = await findAnnouncements("");
  if (announcements.length) return { type: "announcement", row: announcements[0] };

  const infoRows = (await listRows("DepartmentInfo"))
    .filter((row) => isActive(row))
    .sort((a, b) => (new Date(b.LastUpdated || 0).getTime() || 0) - (new Date(a.LastUpdated || 0).getTime() || 0));

  return infoRows.length ? { type: "info", row: infoRows[0] } : null;
}

export async function findTimetable(query = "") {
  const level = extractLevel(query);
  const course = extractCourseCode(query);
  const day = extractDay(query);
  const q = normalize(query);
  return (await listRows("Timetable"))
    .filter((row) => isActive(row))
    .filter((row) => {
      if (level && normalize(row.Level) !== normalize(level)) return false;
      if (course && normalize(row.CourseCode) !== normalize(course)) return false;
      if (day && normalize(row.Day) !== normalize(day)) return false;
      if (!level && !course && !day && q) return containsAny(row, q, ["Level", "CourseCode", "CourseTitle", "Day", "Venue", "LecturerName"]);
      return true;
    })
    .sort((a, b) => `${a.Day} ${a.Time}`.localeCompare(`${b.Day} ${b.Time}`));
}

export async function findCourses(query = "") {
  const course = extractCourseCode(query);
  const q = normalize(course || query);
  return (await listRows("Courses"))
    .filter((row) => isActive(row))
    .filter((row) => containsAny(row, q, ["CourseCode", "CourseTitle", "Level", "Semester", "LecturerName", "Description"]));
}

export async function findLecturers(query = "") {
  const course = extractCourseCode(query);
  const q = normalize(course || query.replace(/^(show|send|find|get|who is|details|lecturer|dr|prof|mr|mrs|miss)\s+/i, ""));
  const lecturers = (await listRows("Lecturers")).filter((row) => isActive(row));
  const direct = lecturers.filter((row) => containsAny(row, q, ["LecturerID", "FullName", "Title", "DepartmentRole", "CoursesTaught", "OfficeLocation", "Email"]));
  if (direct.length) return direct;

  if (course) {
    const courses = await findCourses(course);
    const names = courses.map((row) => normalize(row.LecturerName)).filter(Boolean);
    return lecturers.filter((row) => names.some((name) => normalize(row.FullName).includes(name) || name.includes(normalize(row.FullName))));
  }

  return [];
}

export async function findDepartmentInfo(query = "") {
  const q = normalize(query || "department");
  return (await listRows("DepartmentInfo"))
    .filter((row) => isActive(row))
    .filter((row) => containsAny(row, q, ["InfoType", "Title", "Details", "ContactPerson", "ContactPhone"]));
}

formatters.js.content:
function line(label, value) {
  const text = String(value || "").trim();
  return text ? `${label}: ${text}` : "";
}

function joinLines(lines) {
  return lines.filter(Boolean).join("\n");
}

export function formatAnnouncement(row) {
  return joinLines([
    row.Title || "Department announcement",
    line("Category", row.Category),
    line("Level", row.Level),
    line("Course", row.CourseCode),
    line("Message", row.Message),
    line("Date posted", row.DatePosted),
    line("Expires", row.ExpiryDate)
  ]);
}

export function formatAnnouncementList(rows) {
  return rows.slice(0, 6).map((row, index) => `${index + 1}) ${formatAnnouncement(row)}`).join("\n\n");
}

export function formatCourse(row) {
  return joinLines([
    `${row.CourseCode || "Course"}${row.CourseTitle ? `: ${row.CourseTitle}` : ""}`,
    line("Level", row.Level),
    line("Semester", row.Semester),
    line("Lecturer", row.LecturerName),
    line("Venue", row.Venue),
    line("Schedule", row.Schedule),
    line("Description", row.Description)
  ]);
}

export function formatTimetable(rows) {
  return rows.slice(0, 12).map((row, index) => joinLines([
    `${index + 1}) ${row.Day || "Day not set"} ${row.Time || ""}`.trim(),
    line("Course", `${row.CourseCode || ""} ${row.CourseTitle || ""}`.trim()),
    line("Level", row.Level),
    line("Venue", row.Venue),
    line("Lecturer", row.LecturerName)
  ])).join("\n\n");
}

export function formatLecturer(row) {
  return joinLines([
    row.FullName || "Lecturer",
    line("Title", row.Title),
    line("Department role", row.DepartmentRole),
    line("Office location", row.OfficeLocation),
    line("Phone", row.PhoneNumber),
    line("Email", row.Email),
    line("Courses taught", row.CoursesTaught),
    line("Office hours", row.OfficeHours),
    line("Bio", row.Bio),
    row.PhotoURL ? `Photo: ${row.PhotoURL}` : ""
  ]);
}

export function formatDepartmentInfo(row) {
  return joinLines([
    row.Title || row.InfoType || "Department information",
    line("Details", row.Details),
    line("Contact person", row.ContactPerson),
    line("Contact phone", row.ContactPhone),
    line("Last updated", row.LastUpdated)
  ]);
}

export function formatAdminRecord(row) {
  return Object.entries(row)
    .filter(([key, value]) => !key.startsWith("_") && String(value || "").trim())
    .map(([key, value]) => `${key}: ${value}`)
    .join("\n");
}

googleSheets.js.content:
import { google } from "googleapis";
import { cfg } from "../lib/config.js";
import { log, safeErr } from "../lib/log.js";

export const SHEETS = {
  Announcements: {
    name: "Announcements",
    keyField: "AnnouncementID",
    headers: ["AnnouncementID", "Title", "Category", "Level", "CourseCode", "Message", "DatePosted", "ExpiryDate", "Priority", "Status"]
  },
  Lecturers: {
    name: "Lecturers",
    keyField: "LecturerID",
    headers: ["LecturerID", "FullName", "Title", "DepartmentRole", "OfficeLocation", "PhoneNumber", "Email", "CoursesTaught", "OfficeHours", "Bio", "PhotoURL", "Status"]
  },
  Courses: {
    name: "Courses",
    keyField: "CourseCode",
    headers: ["CourseCode", "CourseTitle", "Level", "Semester", "LecturerName", "Venue", "Schedule", "Description", "Status"]
  },
  Timetable: {
    name: "Timetable",
    keyField: "CourseCode",
    headers: ["Level", "CourseCode", "CourseTitle", "Day", "Time", "Venue", "LecturerName", "Status"]
  },
  DepartmentInfo: {
    name: "DepartmentInfo",
    keyField: "InfoType",
    headers: ["InfoType", "Title", "Details", "ContactPerson", "ContactPhone", "LastUpdated", "Status"]
  }
};

let sheetsClient = null;
let initialized = false;
const cache = new Map();

export function sheetsConfigured() {
  return Boolean(
    cfg.GOOGLE_SHEETS_SPREADSHEET_ID &&
    (cfg.GOOGLE_APPLICATION_CREDENTIALS || (cfg.GOOGLE_SERVICE_ACCOUNT_EMAIL && cfg.GOOGLE_SERVICE_ACCOUNT_PRIVATE_KEY))
  );
}

function sheetDef(sheetKey) {
  const def = SHEETS[sheetKey];
  if (!def) throw new Error(`Unknown sheet: ${sheetKey}`);
  return def;
}

function columnName(index) {
  let n = index;
  let name = "";
  while (n > 0) {
    const mod = (n - 1) % 26;
    name = String.fromCharCode(65 + mod) + name;
    n = Math.floor((n - mod) / 26);
  }
  return name;
}

async function getClient() {
  if (!sheetsConfigured()) {
    throw new Error("Google Sheets is not configured. Set GOOGLE_SHEETS_SPREADSHEET_ID and service account credentials.");
  }

  if (sheetsClient) return sheetsClient;

  let auth;
  if (cfg.GOOGLE_APPLICATION_CREDENTIALS) {
    auth = new google.auth.GoogleAuth({
      keyFile: cfg.GOOGLE_APPLICATION_CREDENTIALS,
      scopes: ["https://www.googleapis.com/auth/spreadsheets"]
    });
  } else {
    auth = new google.auth.JWT({
      email: cfg.GOOGLE_SERVICE_ACCOUNT_EMAIL,
      key: cfg.GOOGLE_SERVICE_ACCOUNT_PRIVATE_KEY,
      scopes: ["https://www.googleapis.com/auth/spreadsheets"]
    });
  }

  sheetsClient = google.sheets({ version: "v4", auth });
  return sheetsClient;
}

async function ensureWorkbook() {
  if (initialized) return;
  const client = await getClient();
  const spreadsheetId = cfg.GOOGLE_SHEETS_SPREADSHEET_ID;

  const meta = await client.spreadsheets.get({ spreadsheetId });
  const existing = new Set((meta.data.sheets || []).map((sheet) => sheet.properties?.title).filter(Boolean));
  const requests = [];

  for (const def of Object.values(SHEETS)) {
    if (!existing.has(def.name)) {
      requests.push({ addSheet: { properties: { title: def.name } } });
    }
  }

  if (requests.length) {
    await client.spreadsheets.batchUpdate({ spreadsheetId, requestBody: { requests } });
    log.info("google sheets created missing tabs", { count: requests.length });
  }

  for (const def of Object.values(SHEETS)) {
    const lastCol = columnName(def.headers.length);
    const range = `'${def.name}'!A1:${lastCol}1`;
    const current = await client.spreadsheets.values.get({ spreadsheetId, range }).catch(() => ({ data: { values: [] } }));
    const headerRow = current.data.values?.[0] || [];
    const needsHeader = def.headers.some((header, index) => headerRow[index] !== header);
    if (needsHeader) {
      await client.spreadsheets.values.update({
        spreadsheetId,
        range,
        valueInputOption: "RAW",
        requestBody: { values: [def.headers] }
      });
    }
  }

  initialized = true;
  log.info("google sheets ready", { spreadsheetConfigured: true });
}

function valuesToRows(values, headers) {
  return values.slice(1).map((row, index) => {
    const item = { _rowNumber: index + 2 };
    headers.forEach((header, i) => {
      item[header] = row[i] || "";
    });
    return item;
  });
}

export async function listRows(sheetKey, { force = false } = {}) {
  const def = sheetDef(sheetKey);
  const cached = cache.get(sheetKey);
  if (!force && cached && Date.now() - cached.ts < cfg.CACHE_TTL_MS) return cached.rows;

  try {
    await ensureWorkbook();
    const client = await getClient();
    const lastCol = columnName(def.headers.length);
    const range = `'${def.name}'!A1:${lastCol}`;
    const res = await client.spreadsheets.values.get({ spreadsheetId: cfg.GOOGLE_SHEETS_SPREADSHEET_ID, range });
    const values = res.data.values || [def.headers];
    const rows = valuesToRows(values, def.headers);
    cache.set(sheetKey, { ts: Date.now(), rows });
    log.info("google sheets read", { collection: def.name, operation: "list", count: rows.length });
    return rows;
  } catch (err) {
    log.error("google sheets read failed", { collection: def.name, operation: "list", error: safeErr(err) });
    throw err;
  }
}

export async function appendRow(sheetKey, record) {
  const def = sheetDef(sheetKey);
  try {
    await ensureWorkbook();
    const client = await getClient();
    const values = def.headers.map((header) => record[header] || "");
    await client.spreadsheets.values.append({
      spreadsheetId: cfg.GOOGLE_SHEETS_SPREADSHEET_ID,
      range: `'${def.name}'!A1`,
      valueInputOption: "USER_ENTERED",
      insertDataOption: "INSERT_ROWS",
      requestBody: { values: [values] }
    });
    cache.delete(sheetKey);
    log.info("google sheets write", { collection: def.name, operation: "append" });
  } catch (err) {
    log.error("google sheets write failed", { collection: def.name, operation: "append", error: safeErr(err) });
    throw err;
  }
}

export async function updateRowByField(sheetKey, field, value, patch) {
  const def = sheetDef(sheetKey);
  const rows = await listRows(sheetKey, { force: true });
  const match = rows.find((row) => String(row[field] || "").trim().toLowerCase() === String(value || "").trim().toLowerCase());
  if (!match) return null;

  const updated = { ...match, ...patch };
  delete updated._rowNumber;
  const values = def.headers.map((header) => updated[header] || "");
  const lastCol = columnName(def.headers.length);

  try {
    const client = await getClient();
    await client.spreadsheets.values.update({
      spreadsheetId: cfg.GOOGLE_SHEETS_SPREADSHEET_ID,
      range: `'${def.name}'!A${match._rowNumber}:${lastCol}${match._rowNumber}`,
      valueInputOption: "USER_ENTERED",
      requestBody: { values: [values] }
    });
    cache.delete(sheetKey);
    log.info("google sheets write", { collection: def.name, operation: "update", field });
    return updated;
  } catch (err) {
    log.error("google sheets write failed", { collection: def.name, operation: "update", error: safeErr(err) });
    throw err;
  }
}

export async function softDeleteRow(sheetKey, field, value) {
  return updateRowByField(sheetKey, field, value, { Status: "deleted" });
}

export async function upsertRowByField(sheetKey, field, value, record) {
  const updated = await updateRowByField(sheetKey, field, value, record);
  if (updated) return { mode: "updated", record: updated };
  await appendRow(sheetKey, record);
  return { mode: "created", record };
}

