export function buildBotProfile() {
  return [
    "Purpose: Official WhatsApp assistant for the Department of Software Engineering, Faculty of Computing and Information Systems, Federal University Wukari.",
    "Source of truth: The bot answers only from configured Google Sheets records for announcements, lecturers, courses, timetables, and department information.",
    "Public student commands: /start, /help, /announcements, /latest, /timetable, /course, /lecturer, /department.",
    "Admin commands: /admin, /addannouncement, /updateannouncement, /deleteannouncement, /activeannouncements, /addlecturer, /updatelecturer, /findlecturer, /addcourse, /updatecourse, /updatetimetable, /departmentinfo.",
    "Rules: Student answers must use active, non-expired records only unless old records are requested. Admin actions require an approved WhatsApp number or access code. If confirmed data is missing, use the exact no-data fallback."
  ].join("\n");
}

export const BOT_PROFILE = buildBotProfile();

config.js.content:
function splitCsv(value) {
  return String(value || "")
    .split(",")
    .map((item) => item.trim())
    .filter(Boolean);
}

function normalizePhone(value) {
  return String(value || "").replace(/\D/g, "");
}

function numberWithDefault(value, fallback) {
  const parsed = Number(value);
  return Number.isFinite(parsed) && parsed >= 0 ? parsed : fallback;
}

export const cfg = {
  WHATSAPP_AUTH_DIR: process.env.WHATSAPP_AUTH_DIR || ".auth/whatsapp",
  WHATSAPP_ADMIN_NUMBERS: splitCsv(process.env.WHATSAPP_ADMIN_NUMBERS || "").map(normalizePhone).filter(Boolean),
  MONGODB_URI: process.env.MONGODB_URI || "",
  GOOGLE_SHEETS_SPREADSHEET_ID: process.env.GOOGLE_SHEETS_SPREADSHEET_ID || "",
  GOOGLE_SERVICE_ACCOUNT_EMAIL: process.env.GOOGLE_SERVICE_ACCOUNT_EMAIL || "",
  GOOGLE_SERVICE_ACCOUNT_PRIVATE_KEY: String(process.env.GOOGLE_SERVICE_ACCOUNT_PRIVATE_KEY || "").replace(/\\n/g, "\n"),
  GOOGLE_APPLICATION_CREDENTIALS: process.env.GOOGLE_APPLICATION_CREDENTIALS || "",
  ADMIN_ACCESS_CODE: process.env.ADMIN_ACCESS_CODE || "",
  CACHE_TTL_MS: numberWithDefault(process.env.CACHE_TTL_MS || "30000", 30000)
};

export function logEnvSanity() {
  console.log("[boot] env sanity", {
    WHATSAPP_AUTH_DIR_set: Boolean(cfg.WHATSAPP_AUTH_DIR),
    WHATSAPP_ADMIN_NUMBERS_count: cfg.WHATSAPP_ADMIN_NUMBERS.length,
    MONGODB_URI_set: Boolean(cfg.MONGODB_URI),
    GOOGLE_SHEETS_SPREADSHEET_ID_set: Boolean(cfg.GOOGLE_SHEETS_SPREADSHEET_ID),
    GOOGLE_SERVICE_ACCOUNT_EMAIL_set: Boolean(cfg.GOOGLE_SERVICE_ACCOUNT_EMAIL),
    GOOGLE_SERVICE_ACCOUNT_PRIVATE_KEY_set: Boolean(cfg.GOOGLE_SERVICE_ACCOUNT_PRIVATE_KEY),
    GOOGLE_APPLICATION_CREDENTIALS_set: Boolean(cfg.GOOGLE_APPLICATION_CREDENTIALS),
    ADMIN_ACCESS_CODE_set: Boolean(cfg.ADMIN_ACCESS_CODE)
  });
}

db.js.content:
import { MongoClient } from "mongodb";
import { log, safeErr } from "./log.js";

let client = null;
let db = null;

export async function getDb(mongoUri) {
  if (!mongoUri) return null;
  if (db) return db;

  try {
    client = new MongoClient(mongoUri, { maxPoolSize: 5, ignoreUndefined: true });
    await client.connect();
    db = client.db();
    await db.collection("memory_messages").createIndex({ platform: 1, userId: 1, chatId: 1, ts: -1 });
    await db.collection("admin_audit").createIndex({ ts: -1 });
    log.info("db connected", { collections: ["memory_messages", "admin_audit"] });
    return db;
  } catch (err) {
    log.error("db connect failed", { collection: "memory_messages", operation: "connect", error: safeErr(err) });
    return null;
  }
}

log.js.content:
export function safeErr(err) {
  return err?.response?.data?.error?.message ||
    err?.response?.data?.message ||
    err?.message ||
    String(err);
}

export const log = {
  info(message, meta = {}) {
    console.log(JSON.stringify({ level: "info", message, ...meta }));
  },
  warn(message, meta = {}) {
    console.warn(JSON.stringify({ level: "warn", message, ...meta }));
  },
  error(message, meta = {}) {
    console.error(JSON.stringify({ level: "error", message, ...meta }));
  }
};

