adminHandlers.js.content:
import { cfg } from "../lib/config.js";
import { log, safeErr } from "../lib/log.js";
import { auditAdminAction } from "../lib/memory.js";
import { appendRow, softDeleteRow, updateRowByField, upsertRowByField } from "../services/googleSheets.js";
import { formatAdminRecord, formatAnnouncementList } from "../services/formatters.js";
import { findAnnouncements, findLecturers } from "../services/departmentRecords.js";

const verifiedAdmins = new Set();
const pendingForms = new Map();

const FORM_DEFS = {
  addannouncement: {
    sheet: "Announcements",
    action: "append",
    keyField: "AnnouncementID",
    fields: ["AnnouncementID", "Title", "Category", "Level", "CourseCode", "Message", "DatePosted", "ExpiryDate", "Priority", "Status"],
    defaults: () => ({ AnnouncementID: `ANN-${Date.now()}`, DatePosted: new Date().toISOString().slice(0, 10), Status: "active" })
  },
  addlecturer: {
    sheet: "Lecturers",
    action: "append",
    keyField: "LecturerID",
    fields: ["LecturerID", "FullName", "Title", "DepartmentRole", "OfficeLocation", "PhoneNumber", "Email", "CoursesTaught", "OfficeHours", "Bio", "PhotoURL", "Status"],
    defaults: () => ({ LecturerID: `LEC-${Date.now()}`, Status: "active" })
  },
  addcourse: {
    sheet: "Courses",
    action: "append",
    keyField: "CourseCode",
    fields: ["CourseCode", "CourseTitle", "Level", "Semester", "LecturerName", "Venue", "Schedule", "Description", "Status"],
    defaults: () => ({ Status: "active" })
  },
  updatetimetable: {
    sheet: "Timetable",
    action: "append",
    keyField: "CourseCode",
    fields: ["Level", "CourseCode", "CourseTitle", "Day", "Time", "Venue", "LecturerName", "Status"],
    defaults: () => ({ Status: "active" })
  },
  departmentinfo: {
    sheet: "DepartmentInfo",
    action: "upsert",
    keyField: "InfoType",
    fields: ["InfoType", "Title", "Details", "ContactPerson", "ContactPhone", "LastUpdated", "Status"],
    defaults: () => ({ LastUpdated: new Date().toISOString().slice(0, 10), Status: "active" })
  }
};

function normalizePhone(value) {
  return String(value || "").replace(/\D/g, "");
}

function userId(ctx) {
  return normalizePhone(ctx.from?.phone || ctx.from?.id || "");
}

function isApprovedId(ctx) {
  const id = userId(ctx);
  return Boolean(id && cfg.WHATSAPP_ADMIN_NUMBERS.includes(id));
}

export function isAdmin(ctx) {
  return isApprovedId(ctx) || verifiedAdmins.has(userId(ctx));
}

function commandArg(ctx) {
  return String(ctx.match || "").trim();
}

function parseKeyValues(text) {
  const result = {};
  const pieces = String(text || "").split(/\n|;/).map((item) => item.trim()).filter(Boolean);
  for (const piece of pieces) {
    const match = piece.match(/^([^:=]+)\s*[:=]\s*([\s\S]*)$/);
    if (match) result[match[1].trim()] = match[2].trim();
  }
  return result;
}

function requireAdminMessage() {
  return "Admin access is required. Use /admin your-access-code first.";
}

async function audit(ctx, action, sheet, target, ok, details = {}) {
  await auditAdminAction({ mongoUri: cfg.MONGODB_URI, userId: userId(ctx), action, sheet, target, ok, details });
}

async function requireAdmin(ctx) {
  if (isAdmin(ctx)) return true;
  await ctx.reply(requireAdminMessage());
  return false;
}

function promptForForm(def, command) {
  return [
    `Send the ${command} details as Field=Value lines.`,
    `Required fields are: ${def.fields.join(", ")}.`,
    "You can send only the fields you know, but key fields should be included.",
    "Example:",
    def.fields.slice(0, 4).map((field) => `${field}=`).join("\n"),
    "Send cancel to stop."
  ].join("\n");
}

async function executeForm(ctx, command, values) {
  const def = FORM_DEFS[command];
  const record = { ...def.defaults(), ...values };
  if (def.action === "upsert") {
    const keyValue = record[def.keyField];
    if (!keyValue) return ctx.reply(`${def.keyField} is required.`);
    const result = await upsertRowByField(def.sheet, def.keyField, keyValue, record);
    await audit(ctx, command, def.sheet, keyValue, true, { mode: result.mode });
    return ctx.reply(`${def.sheet} ${result.mode}.\n\n${formatAdminRecord(record)}`);
  }

  await appendRow(def.sheet, record);
  await audit(ctx, command, def.sheet, record[def.keyField] || "new", true);
  await ctx.reply(`${def.sheet} record added.\n\n${formatAdminRecord(record)}`);
}

export async function handleAdmin(ctx) {
  const arg = commandArg(ctx);
  if (isApprovedId(ctx)) {
    verifiedAdmins.add(userId(ctx));
    await ctx.reply("Admin access confirmed for your WhatsApp number.");
    return;
  }
  if (!cfg.ADMIN_ACCESS_CODE) {
    await ctx.reply("Admin access code is not configured yet. Ask the bot owner to set ADMIN_ACCESS_CODE or WHATSAPP_ADMIN_NUMBERS.");
    return;
  }
  if (!arg) {
    await ctx.reply("Send /admin followed by your access code.");
    return;
  }
  if (arg === cfg.ADMIN_ACCESS_CODE) {
    verifiedAdmins.add(userId(ctx));
    log.info("admin verified", { platform: "whatsapp", userId: userId(ctx) });
    await ctx.reply("Admin access verified. You can now manage department records.");
    return;
  }
  log.warn("admin verification failed", { platform: "whatsapp", userId: userId(ctx) });
  await ctx.reply("Invalid admin access code.");
}

export async function handleCreateForm(ctx, command) {
  if (!(await requireAdmin(ctx))) return;
  const def = FORM_DEFS[command];
  const arg = commandArg(ctx);
  if (!arg) {
    pendingForms.set(String(ctx.chat.id), { command });
    await ctx.reply(promptForForm(def, command));
    return;
  }
  try {
    await executeForm(ctx, command, parseKeyValues(arg));
  } catch (err) {
    await audit(ctx, command, def.sheet, "", false, { error: safeErr(err) });
    await ctx.reply("I could not save that record to Google Sheets. Please check the fields and try again.");
  }
}

export async function handlePendingAdminFlow(ctx, next) {
  const raw = ctx.message?.text || "";
  if (raw.startsWith("/")) return next();
  const key = String(ctx.chat?.id || "");
  const pending = pendingForms.get(key);
  if (!pending) return next();
  if (!(await requireAdmin(ctx))) {
    pendingForms.delete(key);
    return;
  }
  if (raw.trim().toLowerCase() === "cancel") {
    pendingForms.delete(key);
    await ctx.reply("Admin form cancelled.");
    return;
  }
  try {
    await executeForm(ctx, pending.command, parseKeyValues(raw));
  } catch (err) {
    log.error("admin form failed", { command: pending.command, error: safeErr(err) });
    await ctx.reply("I could not save that record to Google Sheets. Please check the fields and try again.");
  } finally {
    pendingForms.delete(key);
  }
}

export async function handleUpdateAnnouncement(ctx) {
  if (!(await requireAdmin(ctx))) return;
  const [id, ...rest] = commandArg(ctx).split(/\s+/);
  if (!id || rest.length === 0) return ctx.reply("Usage: /updateannouncement AnnouncementID Field=Value; Message=Updated text");
  try {
    const updated = await updateRowByField("Announcements", "AnnouncementID", id, parseKeyValues(rest.join(" ")));
    await audit(ctx, "updateannouncement", "Announcements", id, Boolean(updated));
    await ctx.reply(updated ? `Announcement updated.\n\n${formatAdminRecord(updated)}` : "AnnouncementID not found.");
  } catch (err) {
    log.error("announcement update failed", { error: safeErr(err) });
    await ctx.reply("I could not update that announcement.");
  }
}

export async function handleDeleteAnnouncement(ctx) {
  if (!(await requireAdmin(ctx))) return;
  const id = commandArg(ctx);
  if (!id) return ctx.reply("Usage: /deleteannouncement AnnouncementID");
  try {
    const updated = await softDeleteRow("Announcements", "AnnouncementID", id);
    await audit(ctx, "deleteannouncement", "Announcements", id, Boolean(updated));
    await ctx.reply(updated ? "Announcement marked as deleted." : "AnnouncementID not found.");
  } catch (err) {
    log.error("announcement delete failed", { error: safeErr(err) });
    await ctx.reply("I could not delete that announcement.");
  }
}

export async function handleActiveAnnouncements(ctx) {
  if (!(await requireAdmin(ctx))) return;
  try {
    const rows = await findAnnouncements("");
    await ctx.reply(rows.length ? formatAnnouncementList(rows) : "No active announcements found.");
  } catch (err) {
    log.error("active announcements read failed", { error: safeErr(err) });
    await ctx.reply("I could not read active announcements right now.");
  }
}

export async function handleUpdateLecturer(ctx) {
  if (!(await requireAdmin(ctx))) return;
  const [id, ...rest] = commandArg(ctx).split(/\s+/);
  if (!id || rest.length === 0) return ctx.reply("Usage: /updatelecturer LecturerID Field=Value; OfficeHours=...");
  const updated = await updateRowByField("Lecturers", "LecturerID", id, parseKeyValues(rest.join(" ")));
  await audit(ctx, "updatelecturer", "Lecturers", id, Boolean(updated));
  await ctx.reply(updated ? `Lecturer updated.\n\n${formatAdminRecord(updated)}` : "LecturerID not found.");
}

export async function handleFindLecturer(ctx) {
  if (!(await requireAdmin(ctx))) return;
  const query = commandArg(ctx);
  if (!query) return ctx.reply("Usage: /findlecturer Dr Ahmed");
  const rows = await findLecturers(query);
  await ctx.reply(rows.length ? rows.slice(0, 5).map(formatAdminRecord).join("\n\n") : "No lecturer record found.");
}

export async function handleUpdateCourse(ctx) {
  if (!(await requireAdmin(ctx))) return;
  const match = commandArg(ctx).match(/^([A-Za-z]{2,4}\s*-?\s*\d{3})\s+([\s\S]+)$/);
  if (!match) return ctx.reply("Usage: /updatecourse SWE 201 Field=Value; Venue=...");
  const code = match[1].replace(/\s*-\s*/, " ").toUpperCase();
  const updated = await updateRowByField("Courses", "CourseCode", code, parseKeyValues(match[2]));
  await audit(ctx, "updatecourse", "Courses", code, Boolean(updated));
  await ctx.reply(updated ? `Course updated.\n\n${formatAdminRecord(updated)}` : "CourseCode not found.");
}

export async function registerAdminNaturalHandler(bot) {
  bot.on("message:text", handlePendingAdminFlow);
}

studentHandlers.js.content:
import { cfg } from "../lib/config.js";
import { log, safeErr } from "../lib/log.js";
import { addTurn } from "../lib/memory.js";
import { NO_DATA_MESSAGE, extractCourseCode, findAnnouncements, findCourses, findDepartmentInfo, findLatest, findLecturers, findTimetable, normalize } from "../services/departmentRecords.js";
import { formatAnnouncement, formatAnnouncementList, formatCourse, formatDepartmentInfo, formatLecturer, formatTimetable } from "../services/formatters.js";

const GREETING = "Hello, I’m the WhatsApp assistant for the Department of Software Engineering, Faculty of Computing and Information Systems, Federal University Wukari. How can I help you today?";
const GOOGLE_ERROR = "I’m having trouble reaching Google Sheets right now. Please try again shortly.";
const inFlightChats = new Set();
let globalInFlight = 0;
const GLOBAL_CAP = 2;

export function greetingText() {
  return `${GREETING}\n\nYou can ask for the latest announcement, 300 level timetable, department fees, course details, or lecturer details.`;
}

export function helpText() {
  return [
    "Student commands:",
    "/start - Show the official greeting.",
    "/help - Show available commands.",
    "/announcements 300 level - View active announcements.",
    "/latest - Show the latest active announcement or notice.",
    "/timetable 200 level or /timetable today - View timetable entries.",
    "/course SWE 201 - Find course information.",
    "/lecturer Dr Ahmed - Find lecturer details and photo if available.",
    "/department office or /department fees - Get department information.",
    "",
    "Admin commands:",
    "/admin code - Verify admin access.",
    "/addannouncement, /updateannouncement, /deleteannouncement, /activeannouncements.",
    "/addlecturer, /updatelecturer, /findlecturer.",
    "/addcourse, /updatecourse, /updatetimetable, /departmentinfo."
  ].join("\n");
}

function commandArg(ctx) {
  return String(ctx.match || "").trim();
}

async function remember(ctx, role, text) {
  await addTurn({
    mongoUri: cfg.MONGODB_URI,
    platform: "whatsapp",
    userId: ctx.from?.phone || ctx.from?.id,
    chatId: ctx.chat?.id,
    role,
    text
  });
}

async function replyAndRemember(ctx, text) {
  await remember(ctx, "assistant", text);
  await ctx.reply(text);
}

async function runStudent(ctx, intent, fn) {
  const chatKey = String(ctx.chat?.id || ctx.from?.id || "unknown");
  if (inFlightChats.has(chatKey)) {
    await ctx.reply("I’m working on your last request. Please wait a moment.");
    return;
  }
  if (globalInFlight >= GLOBAL_CAP) {
    await ctx.reply("I’m busy right now. Please try again in a moment.");
    return;
  }

  inFlightChats.add(chatKey);
  globalInFlight += 1;
  try {
    log.info("student intent start", { platform: "whatsapp", intent, chatType: ctx.chat?.type || "unknown" });
    await fn();
    log.info("student intent success", { platform: "whatsapp", intent });
  } catch (err) {
    log.error("student intent failed", { platform: "whatsapp", intent, error: safeErr(err) });
    await ctx.reply(GOOGLE_ERROR);
  } finally {
    inFlightChats.delete(chatKey);
    globalInFlight = Math.max(0, globalInFlight - 1);
  }
}

export async function handleStart(ctx) {
  await replyAndRemember(ctx, greetingText());
}

export async function handleHelp(ctx) {
  await replyAndRemember(ctx, helpText());
}

export async function handleAnnouncements(ctx, query = commandArg(ctx)) {
  await remember(ctx, "user", `/announcements ${query}`.trim());
  await runStudent(ctx, "announcements", async () => {
    const rows = await findAnnouncements(query);
    await replyAndRemember(ctx, rows.length ? formatAnnouncementList(rows) : NO_DATA_MESSAGE);
  });
}

export async function handleLatest(ctx) {
  await remember(ctx, "user", "/latest");
  await runStudent(ctx, "latest", async () => {
    const item = await findLatest();
    if (!item) return replyAndRemember(ctx, NO_DATA_MESSAGE);
    const text = item.type === "announcement" ? formatAnnouncement(item.row) : formatDepartmentInfo(item.row);
    await replyAndRemember(ctx, text || NO_DATA_MESSAGE);
  });
}

export async function handleTimetable(ctx, query = commandArg(ctx)) {
  await remember(ctx, "user", `/timetable ${query}`.trim());
  await runStudent(ctx, "timetable", async () => {
    const rows = await findTimetable(query);
    await replyAndRemember(ctx, rows.length ? formatTimetable(rows) : NO_DATA_MESSAGE);
  });
}

export async function handleCourse(ctx, query = commandArg(ctx)) {
  await remember(ctx, "user", `/course ${query}`.trim());
  await runStudent(ctx, "course", async () => {
    const rows = await findCourses(query);
    await replyAndRemember(ctx, rows.length ? rows.slice(0, 3).map(formatCourse).join("\n\n") : NO_DATA_MESSAGE);
  });
}

async function sendLecturerPhoto(ctx, row) {
  const url = String(row.PhotoURL || "").trim();
  if (!url) return;

  try {
    const res = await fetch(url);
    if (!res.ok) throw new Error(`photo download failed ${res.status}`);
    const buffer = Buffer.from(await res.arrayBuffer());
    await ctx.sendImage({ buffer, url, caption: "Lecturer photo" });
  } catch (err) {
    log.warn("whatsapp lecturer photo fallback link", { error: safeErr(err), hasUrl: Boolean(url) });
    await ctx.reply(`Lecturer photo: ${url}`);
  }
}

export async function handleLecturer(ctx, query = commandArg(ctx)) {
  await remember(ctx, "user", `/lecturer ${query}`.trim());
  await runStudent(ctx, "lecturer", async () => {
    const rows = await findLecturers(query);
    if (!rows.length) return replyAndRemember(ctx, NO_DATA_MESSAGE);
    const row = rows[0];
    await replyAndRemember(ctx, formatLecturer(row));
    await sendLecturerPhoto(ctx, row);
  });
}

export async function handleDepartment(ctx, query = commandArg(ctx)) {
  await remember(ctx, "user", `/department ${query}`.trim());
  await runStudent(ctx, "department", async () => {
    const rows = await findDepartmentInfo(query || "department");
    await replyAndRemember(ctx, rows.length ? rows.slice(0, 4).map(formatDepartmentInfo).join("\n\n") : NO_DATA_MESSAGE);
  });
}

function shouldHandleMessage(ctx, raw) {
  if (ctx.chat?.type === "private") return true;
  const q = normalize(raw);
  return q.startsWith("bot ") || q.includes("department assistant");
}

async function routeNatural(ctx, text) {
  const q = normalize(text);
  if (/^(hi|hello|hey|good morning|good afternoon|good evening)\b/.test(q)) return handleStart(ctx);
  if (q.includes("announcement") || q.includes("notice") || q.includes("test") || q.includes("exam") || q.includes("lecture update") || q.includes("latest")) {
    if (q.includes("latest")) return handleLatest(ctx);
    return handleAnnouncements(ctx, text);
  }
  if (q.includes("timetable") || q.includes("schedule") || q.includes("today") || q.includes("lecture")) return handleTimetable(ctx, text);
  if (q.includes("lecturer") || q.includes("teacher") || q.includes("teaches") || q.includes("picture") || q.includes("photo") || /\b(dr|prof|mr|mrs|miss)\b/.test(q)) return handleLecturer(ctx, text);
  if (extractCourseCode(text) || q.includes("course")) return handleCourse(ctx, text);
  if (q.includes("department") || q.includes("faculty") || q.includes("fees") || q.includes("fee") || q.includes("deadline") || q.includes("office") || q.includes("hod") || q.includes("head of department") || q.includes("contact") || q.includes("venue")) return handleDepartment(ctx, text);
  return replyAndRemember(ctx, NO_DATA_MESSAGE);
}

export function registerStudentNaturalHandler(bot) {
  bot.on("message:text", async (ctx, next) => {
    const raw = ctx.message?.text || "";
    if (raw.startsWith("/")) return next();
    if (!shouldHandleMessage(ctx, raw)) return next();
    const text = raw.replace(/^bot\s+/i, "").trim();
    if (!text) return ctx.reply(greetingText());
    await remember(ctx, "user", text);
    await routeNatural(ctx, text);
  });
}

index.js.content:
import "dotenv/config";
import { cfg, logEnvSanity } from "./lib/config.js";
import { log, safeErr } from "./lib/log.js";

let botInstance = null;
let stopping = false;

process.on("unhandledRejection", (err) => {
  log.error("unhandled rejection", { error: safeErr(err) });
  process.exit(1);
});

process.on("uncaughtException", (err) => {
  log.error("uncaught exception", { error: safeErr(err) });
  process.exit(1);
});

function logMemory() {
  const m = process.memoryUsage();
  console.log("[mem]", { rssMB: Math.round(m.rss / 1e6), heapUsedMB: Math.round(m.heapUsed / 1e6) });
}

async function stopBot() {
  if (!botInstance) return;
  try {
    await botInstance.stop();
  } catch (err) {
    log.warn("whatsapp stop failed", { error: safeErr(err) });
  } finally {
    botInstance = null;
  }
}

async function boot() {
  try {
    log.info("boot start", { platform: "whatsapp" });
    logEnvSanity();

    const { createBot, registerBotFeatures } = await import("./bot.js");
    const { registerCommands } = await import("./commands/loader.js");

    botInstance = createBot();
    await registerCommands(botInstance);
    registerBotFeatures(botInstance);

    setInterval(logMemory, 60000).unref();

    process.once("SIGTERM", async () => {
      stopping = true;
      await stopBot();
      process.exit(0);
    });
    process.once("SIGINT", async () => {
      stopping = true;
      await stopBot();
      process.exit(0);
    });

    await botInstance.start();
    log.info("whatsapp bot started", { authDirSet: Boolean(cfg.WHATSAPP_AUTH_DIR), stopping });
  } catch (err) {
    log.error("boot failure", { error: safeErr(err), code: err?.code || "" });
    if (err?.code === "ERR_MODULE_NOT_FOUND") {
      console.error("Check that all imported files exist and relative ESM imports include .js extensions.");
    }
    process.exit(1);
  }
}

boot();

